def _processing_source_value(value):
    """Keep source values, including false/zero and explicit empty structures."""
    if value is None:
        return ""
    if isinstance(value, (dict, list)):
        return json.dumps(value, ensure_ascii=False, separators=(",", ":"), allow_nan=False)
    return value


def _processing_money(value, field):
    if value is None or isinstance(value, bool):
        raise CrawlerError("data_invalid", f"Missing or invalid quote field: {field}")
    try:
        amount = Decimal(str(value))
    except (InvalidOperation, ValueError, TypeError) as exc:
        raise CrawlerError("data_invalid", f"Invalid amount in {field}") from exc
    if not amount.is_finite() or amount < 0:
        raise CrawlerError("data_invalid", f"Non-finite or negative amount in {field}")
    return amount


def _processing_decimal_text(amount):
    text = format(amount, "f")
    return text.rstrip("0").rstrip(".") if "." in text else text


def _processing_currency(value):
    if not isinstance(value, str) or len(value) != 3 or not value.isascii() or not value.isalpha():
        raise CrawlerError("data_invalid", "Quote currency is missing or invalid")
    code = value.upper()
    return "CNY" if code == "RMB" else code


def _processing_quote(price, currency):
    """Preserve explicit components; absence is partial data, never invented tax."""
    base = _processing_money(price.get("adultPrice"), "adultPrice")
    tax = None
    if price.get("adultTax") is not None and price.get("adultTax") != "":
        tax = _processing_money(price["adultTax"], "adultTax")
    elif price.get("freeOilFeeAndTax") is True:
        tax = Decimal(0)
    # Luggage criteria is an observed explicit total/currency contract.  Its
    # absence is common for domestic quotes.  sortPrice and ancillary package
    # prices do not establish tax, total or currency.
    embedded_currency, embedded_total = None, None
    if price.get("luggageVisaKey") not in (None, ""):
        try:
            baggage = json.loads(price["luggageVisaKey"])
            criteria = baggage["criteria"]
            if not isinstance(criteria, dict):
                raise ValueError("criteria")
            if criteria.get("Currency") not in (None, ""):
                embedded_currency = _processing_currency(criteria["Currency"])
            if criteria.get("TotalPrice") not in (None, ""):
                embedded_total = _processing_money(criteria["TotalPrice"], "criteria.TotalPrice")
        except (TypeError, ValueError, KeyError) as exc:
            raise CrawlerError("data_invalid", "Invalid luggageVisaKey quote criteria") from exc
    total = base + tax if tax is not None else embedded_total
    if embedded_total is not None:
        if embedded_total < base or (tax is not None and embedded_total != base + tax):
            raise CrawlerError("data_invalid", "Quote total conflicts with its explicit components")
    currencies = {_processing_currency(value) for value in
                  (price.get("currency"), price.get("currencyCode"), currency, embedded_currency)
                  if value is not None and value != ""}
    if len(currencies) > 1:
        raise CrawlerError("data_invalid", "Quote currency conflicts with its explicit criteria")
    quote_currency = next(iter(currencies), None)
    missing = []
    if quote_currency is None:
        missing.append("currency_missing")
    if tax is None:
        missing.append("tax_missing")
    if total is None:
        missing.append("total_missing")
    return {"base": base, "tax": tax, "total": total, "currency": quote_currency,
            "complete": not missing, "missing": missing,
            "legacy_full": _processing_source_value(price.get("miseryIndex"))}


def _processing_datetime(value, field):
    if not isinstance(value, str):
        raise CrawlerError("data_invalid", f"Missing datetime field {field}")
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError as exc:
        raise CrawlerError("data_invalid", f"Invalid datetime field {field}") from exc
    return parsed.date().isoformat(), parsed.time().isoformat(timespec="seconds")


def normalize_response(payload: dict, task: dict, options: dict, observed_at: str) -> dict:
    """Normalize one adapter-confirmed complete search response without I/O."""
    data = payload.get("data") if isinstance(payload, dict) else None
    if not isinstance(data, dict) or not isinstance(data.get("flightItineraryList"), list):
        raise CrawlerError("protocol_changed", "Expected data.flightItineraryList list")
    if not options.get("direct_flight", True):
        raise CrawlerError("unsupported_mode", "Only complete direct-flight itineraries are currently supported")
    items = data["flightItineraryList"]
    try:
        observed_time = datetime.fromisoformat(observed_at.replace("Z", "+00:00"))
    except (AttributeError, TypeError, ValueError) as exc:
        raise CrawlerError("data_invalid", "Invalid observation timestamp") from exc
    if observed_time.tzinfo is None:
        raise CrawlerError("data_invalid", "Observation timestamp must include its UTC offset")
    observed_day = observed_time.astimezone(ZoneInfo(options.get("timezone", "Asia/Shanghai"))).date().isoformat()
    comfort_status = "unavailable" if options.get("comft_flight", False) else "not_requested"
    rows = []
    max_rows = options.get('max_rows')
    price_reasons = set()
    identities = set()
    response_currencies = {_processing_currency(value) for value in
                           (data.get("currency"), data.get("currencyCode"))
                           if value is not None and value != ""}
    if len(response_currencies) > 1:
        raise CrawlerError("data_invalid", "Search response has conflicting currency sources")
    default_currency = next(iter(response_currencies), None)
    for item in items:
        if not isinstance(item, dict):
            raise CrawlerError("protocol_changed", "Itinerary must be an object")
        identity = item.get("itineraryId")
        segments = item.get("flightSegments")
        if not isinstance(identity, str) or not identity or not isinstance(segments, list) or not segments:
            raise CrawlerError("protocol_changed", "Itinerary identity or segments are missing")
        if identity in identities:
            raise CrawlerError("data_invalid", "Duplicate itinerary identity in complete response")
        identities.add(identity)
        if len(segments) != 1:
            raise CrawlerError("data_invalid", "Direct itinerary contains multiple flight segments")
        segment = segments[0]
        if not isinstance(segment, dict) or not isinstance(segment.get("transferCount"), int):
            raise CrawlerError("protocol_changed", "Itinerary transferCount is missing")
        if segment["transferCount"] != 0:
            continue
        flights = segment.get("flightList")
        if not isinstance(flights, list) or len(flights) != 1 or not isinstance(flights[0], dict):
            raise CrawlerError("data_invalid", "Direct itinerary must contain exactly one flight record")
        flight = flights[0]
        for field in ("flightNo", "departureAirportCode", "arrivalAirportCode"):
            if not isinstance(flight.get(field), str) or not flight[field]:
                raise CrawlerError("data_invalid", f"Flight identity field is missing: {field}")
        departure_day, departure_time = _processing_datetime(flight.get("departureDateTime"), "departureDateTime")
        arrival_day, arrival_time = _processing_datetime(flight.get("arrivalDateTime"), "arrivalDateTime")
        if task.get("departure_date") and departure_day != task["departure_date"]:
            raise CrawlerError("data_invalid", "Itinerary departure date differs from current task")
        origin = task.get("origin", {})
        destination = task.get("destination", {})
        for side, expected in (("departure", origin), ("arrival", destination)):
            code = flight.get(side + "CityCode")
            if code and expected.get("code") and code.upper() != expected["code"].upper():
                raise CrawlerError("data_invalid", "Itinerary city code differs from current task")
        prices = item.get("priceList")
        if not isinstance(prices, list):
            raise CrawlerError("protocol_changed", "Itinerary priceList must be a list")
        candidates = {"Y": [], "C": []}
        currencies = set()
        unknown_currency = False
        row_reasons = set()
        for price in prices:
            if not isinstance(price, dict) or "cabin" not in price:
                raise CrawlerError("protocol_changed", "Quote cabin is missing")
            cabin = price["cabin"]
            if cabin not in ("Y", "C"):
                continue
            parsed = _processing_quote(price, default_currency)
            candidates[cabin].append(parsed)
            row_reasons.update(parsed["missing"])
            if parsed["currency"] is None:
                unknown_currency = True
            else:
                currencies.add(parsed["currency"])
        if len(currencies) > 1:
            raise CrawlerError("data_invalid", "Cannot compare itinerary quotes in multiple currencies")
        if not any(candidates.values()):
            row_reasons.add("no_target_quote")
        row_price_status = "partial" if row_reasons else "complete"
        price_reasons.update(row_reasons)
        row = dict.fromkeys(CSV_FIELDS, "")
        row.update({name: _processing_source_value(flight.get(name)) for name in LEGACY_FLIGHT_FIELDS})
        row.update({
            "批次标识": task.get("run_id", ""), "任务标识": task.get("key", ""), "行程标识": identity,
            "采集时间": observed_at, "数据获取日期": observed_day, "航班号": flight["flightNo"],
            "实际承运航班号": flight.get("operateFlightNo", ""), "航空公司": flight.get("marketAirlineName", ""),
            "出发日期": departure_day, "出发时间": departure_time, "到达日期": arrival_day, "到达时间": arrival_time,
            "飞行时长": flight.get("duration", ""), "出发国家": flight.get("departureCountryName", ""),
            "出发城市": flight.get("departureCityName") or origin.get("name", ""),
            "出发机场": flight.get("departureAirportName", ""), "出发机场三字码": flight["departureAirportCode"],
            "到达国家": flight.get("arrivalCountryName", ""), "到达城市": flight.get("arrivalCityName") or destination.get("name", ""),
            "到达机场": flight.get("arrivalAirportName", ""), "到达机场三字码": flight["arrivalAirportCode"],
            "飞机型号": flight.get("aircraftName", ""), "飞机尺寸": flight.get("aircraftSize", ""),
            "飞机型号三字码": flight.get("aircraftCode", ""), "停留次数": flight.get("stopCount", ""),
            "币种": next(iter(currencies), "") if not unknown_currency else "",
            "价格状态": row_price_status, "价格不完整原因": ";".join(sorted(row_reasons)),
            "舒适度状态": comfort_status,
        })
        stops = flight.get("stopList") or []
        if not isinstance(stops, list) or any(not isinstance(stop, dict) for stop in stops):
            raise CrawlerError("data_invalid", "Invalid stopList")
        row["中转信息"] = " -> ".join(f"{stop.get('cityName', '')}({stop.get('airportName', '')}, {stop.get('duration', '')}分钟)" for stop in stops) or "无中转"
        for cabin, prefix, label in (("Y", "economy", "经济舱"), ("C", "bussiness", "商务舱")):
            quotes = candidates[cabin]
            if not quotes:
                row[label + "价格状态"] = "not_available"
                continue
            complete = all(quote["complete"] for quote in quotes)
            if complete:
                selected = min(quotes, key=lambda quote: quote["total"])
                basis = "total_fare"
            else:
                selected = min(quotes, key=lambda quote: quote["base"])
                # This is only the minimum source adultPrice number when any
                # candidate omits currency, not a same-currency price claim.
                basis = "base_fare_currency_unknown" if any(quote["currency"] is None for quote in quotes) else "base_fare"
            row[label + "价格状态"] = "complete" if complete else "partial"
            row[label + "比较口径"] = basis
            row[label + "币种"] = selected["currency"] or ""
            row[prefix + "_full"] = selected["legacy_full"]
            for suffix, field in (("origin", "base"), ("tax", "tax"), ("total", "total")):
                value = selected[field]
                row[f"{prefix}_{suffix}"] = _processing_decimal_text(value) if value is not None else ""
        rows.append(row)
        if max_rows is not None and len(rows) > max_rows:
            raise CrawlerError('response_too_large', 'Qualified itinerary rows exceed the configured limit')
    columns = CSV_FIELDS
    if options.get("rename_col", True) is False:
        rows = [{internal: row[label] for internal, label in CSV_COLUMNS} for row in rows]
        columns = CSV_INTERNAL_FIELDS
    return {"rows": rows, "columns": list(columns), "status": "succeeded" if rows else "empty",
            "observed_at": observed_at, "comfort_status": comfort_status,
            "price_status": "not_applicable" if not rows else ("partial" if price_reasons else "complete"),
            "price_reason": sorted(price_reasons)}


def _processing_comfort_data(payload):
    if (not isinstance(payload, dict) or type(payload.get("status")) is not int
            or payload["status"] != 0 or payload.get("msg") != "success"):
        return None
    data = payload.get("data")
    if not isinstance(data, dict):
        return None
    punctuality, plane, cabins = data.get("punctualityInfo"), data.get("planeInfo"), data.get("cabinInfoList")
    if not isinstance(punctuality, dict) or not isinstance(plane, dict) or not isinstance(cabins, list):
        return None
    values = {}
    for source, mapping in (
        (punctuality, {"departureDelaytime": "出发延误时间", "departureBridge": "出发廊桥率", "arrivalDelaytime": "到达延误时间"}),
        (plane, {"planeTypeName": "飞机类型", "planeWidthCategory": "飞机宽度", "planeAge": "飞机机龄"}),
    ):
        for key, label in mapping.items():
            if key in source and source[key] is not None and isinstance(source[key], (str, int, float, bool)):
                values[label] = source[key]
    for cabin in cabins:
        if not isinstance(cabin, dict) or cabin.get("cabin") not in ("Y", "C"):
            continue
        name = "经济舱" if cabin["cabin"] == "Y" else "商务舱"
        fields = {"hasMeal": "餐食标记（原值）", "mealMsg": "餐食信息", "power": "电源"}
        for key, label in fields.items():
            value = cabin.get(key)
            if value is not None and isinstance(value, (str, int, float, bool)):
                values[name + label] = value
        for key, label in (("seatTilt", "座椅倾斜度"), ("seatWidth", "座椅宽度"), ("seatPitch", "座椅间距")):
            seat = cabin.get(key)
            if isinstance(seat, dict) and seat.get("value") is not None and isinstance(seat["value"], (str, int, float, bool)):
                value = seat["value"]
                # The source page displays these numeric sentinel values as unknown.
                if isinstance(value, (int, float)) and (value == 0 if key == "seatTilt" else -0.5 <= value < 0.5):
                    continue
                values[name + label] = seat["value"]
    return values


def apply_comfort(rows, responses):
    """Attach known comfort responses by operating flight, preserving quotes."""
    if not rows:
        return {"rows": [], "comfort_status": "not_applicable"}
    by_flight = {}
    for response in responses:
        if not isinstance(response, dict) or not isinstance(response.get("flight_no"), str):
            continue
        values = _processing_comfort_data(response.get("payload"))
        if values:
            by_flight[response["flight_no"]] = values
    result = []
    statuses = []
    common = {"出发延误时间", "出发廊桥率", "到达延误时间", "飞机类型", "飞机宽度", "飞机机龄"}
    for original in rows:
        row = dict(original)
        english = "flightNo" in row and "航班号" not in row

        def column(label):
            return CSV_INTERNAL_NAMES[label] if english else label

        number = row.get(column("实际承运航班号")) or row.get(column("航班号"))
        values = by_flight.get(number, {})
        required = set(common)
        for prefix, name in (("economy", "经济舱"), ("bussiness", "商务舱")):
            if row.get(prefix + "_origin") not in (None, ""):
                required.update(name + suffix for suffix in ("餐食信息", "座椅倾斜度", "座椅宽度", "座椅间距"))
        status = "complete" if required.issubset(values) else ("partial" if values else "unavailable")
        for label, value in values.items():
            row[column(label)] = value
        row[column("舒适度状态")] = status
        result.append(row)
        statuses.append(status)
    status = "complete" if all(item == "complete" for item in statuses) else (
        "unavailable" if all(item == "unavailable" for item in statuses) else "partial")
    return {"rows": result, "comfort_status": status,
            "comfort_reason": None if status == "complete" else "missing_or_incomplete_comfort_response"}

# ================ browser ================
# Browser dependencies are imported lazily so --help works without installation.
CAMOUFOX_BUILD = "official/152.0.4-beta.29"
CTRIP_HOME = "https://flights.ctrip.com/online/channel/domestic"
SEARCH_API_PATH = "/international/search/api/search/batchSearch"


def browser_environment_check():
    """Check installed assets without downloading or starting a collection."""
    import subprocess
    from camoufox.fpgen_model import is_pinned
    from camoufox.multiversion import find_installed_version
    from camoufox.pkgman import launch_path
    installed = find_installed_version(CAMOUFOX_BUILD)
    if installed is None:
        raise CrawlerError("browser_missing", "Install the pinned Camoufox browser: python -m camoufox fetch " + CAMOUFOX_BUILD)
    if not is_pinned():
        raise CrawlerError("browser_missing", "Install the pinned fingerprint model explicitly: python -c \"from camoufox.fpgen_model import ensure_fpgen_model; ensure_fpgen_model()\"")
    try:
        checked = subprocess.run([launch_path(installed), "--version"], capture_output=True,
                                 timeout=10, check=False)
    except (OSError, subprocess.TimeoutExpired) as exc:
        raise CrawlerError("browser_unavailable", "The installed Camoufox executable cannot start; check its platform dependencies") from exc
    if checked.returncode:
        raise CrawlerError("browser_unavailable", "The installed Camoufox executable failed its startup check")
    return {"browser_build": CAMOUFOX_BUILD, "installed": True}


def generate_identity(config):
    """Resolve one identity once; the caller persists it before browser launch."""
    from camoufox.fingerprints import get_random_preset
    from camoufox.addons import DefaultAddons
    from camoufox.multiversion import find_installed_version
    from camoufox.pkgman import launch_path
    from camoufox.utils import launch_options

    installed = find_installed_version(CAMOUFOX_BUILD)
    if not installed:
        raise CrawlerError("browser_missing", "Install the pinned Camoufox browser: python -m camoufox fetch " + CAMOUFOX_BUILD)
    operating_system = {"Windows": "windows", "Linux": "linux", "Darwin": "macos"}.get(platform.system())
    if operating_system is None:
        raise CrawlerError("platform_unsupported", "Camoufox requires a supported desktop operating system")
    preset = get_random_preset(os=operating_system, ff_version=CAMOUFOX_BUILD.split("/")[-1].split(".")[0])
    if not preset:
        raise CrawlerError("identity_unavailable", "The pinned package has no fingerprint preset for this platform")
    options = launch_options(executable_path=launch_path(installed), fingerprint_preset=copy.deepcopy(preset),
                             os=operating_system, headless=bool(config.get("headless", True)),
                             locale="zh-CN", env={}, pin_cpu_cores=False,
                             exclude_addons=list(DefaultAddons))
    # env={} prevents credentials and unrelated host variables entering session.json.
    options["env"] = {key: value for key, value in options["env"].items()
                      if key.startswith("CAMOU_") or key == "FONTCONFIG_FILE"}
    identity = {"schema": 1, "platform": platform.system(), "browser_build": CAMOUFOX_BUILD,
                "identity_id": uuid.uuid4().hex, "preset": preset, "launch": options}
    # Refuse an identity that cannot be persisted without custom encoders.
    json.dumps(identity, ensure_ascii=False, allow_nan=False)
    return identity


def identity_launch_options(identity, config):
    if (not isinstance(identity, dict) or identity.get("schema") != 1
            or identity.get("platform") != platform.system()
            or identity.get("browser_build") != CAMOUFOX_BUILD):
        raise CrawlerError("identity_incompatible", "Saved browser identity requires explicit recreation on this platform/build")
    options = copy.deepcopy(identity["launch"])
    options["env"] = {**os.environ, **options.get("env", {})}
    if platform.system() == "Linux":
        binary_directory = str(Path(options["executable_path"]).parent)
        options["env"]["LD_LIBRARY_PATH"] = binary_directory + (
            ":" + options["env"]["LD_LIBRARY_PATH"] if options["env"].get("LD_LIBRARY_PATH") else "")
        runtime = options["env"].get("XDG_RUNTIME_DIR")
        if runtime and config.get("headless", True):
            try:
                if Path(runtime).stat().st_uid != os.getuid():
                    options["env"].pop("XDG_RUNTIME_DIR", None)
            except OSError:
                options["env"].pop("XDG_RUNTIME_DIR", None)
    options["headless"] = bool(config.get("headless", True))
    proxy = config.get("proxy")
    if proxy:
        options["proxy"] = {"server": proxy} if isinstance(proxy, str) else copy.deepcopy(proxy)
    return options


def search_request_matches(payload, task):
    """Only the current single-adult, one-way query is eligible for capture."""
    if not isinstance(payload, dict):
        return False
    segments = payload.get("flightSegments")
    if not isinstance(segments, list) or len(segments) != 1 or not isinstance(segments[0], dict):
        return False
    segment = segments[0]
    if (segment.get("departureCityCode") != task["origin"]["code"]
            or segment.get("arrivalCityCode") != task["destination"]["code"]
            or segment.get("departureDate") != task["departure_date"]):
        return False
    return (type(payload.get("adultCount")) is int and payload["adultCount"] == 1
            and type(payload.get("childCount")) is int and payload["childCount"] == 0
            and type(payload.get("infantCount")) is int and payload["infantCount"] == 0
            and payload.get("flightWay") == "S" and payload.get("cabin") == "Y_S_C_F")


def resolve_city_payload(payload, requested_name):
    if (not isinstance(payload, dict) or payload.get("Status") != 0
            or payload.get("Key") != requested_name or not isinstance(payload.get("Data"), list)):
        raise CrawlerError("protocol_changed", "City suggestions do not match the requested city")
    candidates = {}
    for entry in payload["Data"]:
        if not isinstance(entry, dict) or entry.get("Type") != 5 or entry.get("canSelect") is not True:
            continue
        if (not isinstance(entry.get("Code"), str) or not re.fullmatch(r"[A-Z]{3}", entry["Code"])
                or not isinstance(entry.get("Name"), str) or not entry["Name"]):
            raise CrawlerError("protocol_changed", "City suggestion has an invalid identity")
        candidates[entry["Code"]] = entry
    exact = [entry for entry in candidates.values()
             if requested_name.casefold() in (entry["Name"].casefold(), str(entry.get("EName", "")).casefold(), entry["Code"].casefold())]
    choices = exact if exact else list(candidates.values())
    if len(choices) != 1:
        raise CrawlerError("city_ambiguous", "City name is absent or ambiguous; use its precise city name")
    return {"code": choices[0]["Code"], "name": choices[0]["Name"]}


def member_authenticated(payload):
    if not isinstance(payload, dict):
        return False
    status = payload.get("ResponseStatus")
    result = payload.get("result")
    return (isinstance(status, dict) and status.get("Ack") == "Success"
            and "Errors" in status and isinstance(status["Errors"], list) and not status["Errors"]
            and isinstance(result, dict) and type(result.get("resultCode")) is int
            and result["resultCode"] == 0)


def is_member_summary_request(url, method):
    parsed = urlparse(url)
    return (parsed.scheme == "https" and parsed.hostname == "m.ctrip.com"
            and parsed.path == "/restapi/soa2/15201/getMemberSummaryInfo" and method == "POST")


async def accept_login_agreement(page, timeout_ms):
    checkbox = page.locator("#checkboxAgreementInput")
    if not await checkbox.is_checked(timeout=timeout_ms):
        await page.locator('label[for="checkboxAgreementInput"]').click(timeout=timeout_ms)
    if not await checkbox.is_checked(timeout=timeout_ms):
        raise CrawlerError("auth_failed", "The login agreement was not selected")


def comfort_target_aliases(rows):
    aliases = {}
    for row in rows:
        marketing = row.get("航班号") or row.get("flightNo")
        operating = row.get("实际承运航班号") or row.get("operateFlightNo") or marketing
        for number in (marketing, operating):
            if number:
                aliases.setdefault(number, set()).add(operating)
    return {number: next(iter(targets)) for number, targets in aliases.items() if len(targets) == 1}


def comfort_request_identity(payload, task, aliases):
    if (not isinstance(payload, dict)
            or payload.get("departureCityCode") != task["origin"]["code"]
            or payload.get("arrivalCityCode") != task["destination"]["code"]
            or payload.get("departureDate") != task["departure_date"]):
        return None
    numbers = payload.get("flightNoList")
    if not isinstance(numbers, list) or len(numbers) != 1 or not isinstance(numbers[0], str):
        return None
    operating = aliases.get(numbers[0])
    if not operating:
        return None
    return operating, json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


class SearchChain:
    """Linked nonempty snapshots replace each other; empty pulls retain them."""
    def __init__(self, task):
        self.task = task
        self.search_id = None
        self.transaction_id = None
        self.itineraries = None

    def matches_request(self, path, method, request_payload):
        if method != "POST" or not search_request_matches(request_payload, self.task):
            return False
        if self.search_id is None:
            if path != SEARCH_API_PATH:
                return False
        elif path != "/international/search/api/search/pull/" + self.search_id:
            return False
        transaction_id = request_payload.get("transactionID")
        if not isinstance(transaction_id, str) or not transaction_id:
            raise CrawlerError("protocol_changed", "Search request has no transaction identity")
        return self.search_id is None or transaction_id == self.transaction_id

    def accept(self, path, method, request_payload, http_status, payload):
        if not self.matches_request(path, method, request_payload):
            return None
        if http_status == 429:
            raise CrawlerError("rate_limited", "The search service requested a cooling period")
        if http_status >= 500:
            raise CrawlerError("network_error", "The search service is temporarily unavailable")
        if http_status != 200:
            raise CrawlerError("site_blocked", "The search response did not have a successful HTTP status")
        if not isinstance(payload, dict) or payload.get("status") != 0 or not isinstance(payload.get("data"), dict):
            raise CrawlerError("protocol_changed", "The search service did not return the expected business response")
        data = payload["data"]
        if data.get("needUserLogin") is True:
            raise CrawlerError("needs_auth", "The current search requires authentication")
        context = data.get("context")
        if isinstance(context, dict) and context.get("showAuthCode") is True:
            raise CrawlerError("challenge", "The current search requires human verification")
        if (not isinstance(context, dict) or type(context.get("finished")) is not bool
                or not isinstance(context.get("searchId"), str) or not context["searchId"]):
            raise CrawlerError("protocol_changed", "Search completion or itinerary structure is missing")
        if "flightItineraryList" in data:
            itineraries = data["flightItineraryList"]
            if not isinstance(itineraries, list):
                raise CrawlerError("protocol_changed", "Search itinerary structure is invalid")
        elif not context["finished"] or self.itineraries is None:
            raise CrawlerError("protocol_changed", "Search response has no known itinerary snapshot")
        else:
            itineraries = None
        self.transaction_id = request_payload["transactionID"]
        self.search_id = context["searchId"]
        # The site's SEARCH_FLIGHTS reducer retains a nonempty list when a
        # later pull carries no itineraries, while still applying isFinished.
        # Nonempty responses replace the snapshot; they are never appended.
        if itineraries or self.itineraries is None:
            self.itineraries = itineraries
        if not context["finished"]:
            return None
        if itineraries is not None and (itineraries or not self.itineraries):
            return payload
        completed = copy.deepcopy(payload)
        completed["data"]["flightItineraryList"] = copy.deepcopy(self.itineraries)
        self.itineraries = None
        return completed


class BrowserSession:
    def __init__(self, config, identity, state, emit):
        self.config = config
        self.identity = identity
        self.state = state or {}
        self.emit = emit
        self.manager = None
        self.browser = None
        self.context = None
        self.challenge_page = None
        self.challenge_handle = None
        self.auth_checkpoint = None

    async def start(self):
        from camoufox.async_api import AsyncCamoufox
        self.manager = AsyncCamoufox(from_options=identity_launch_options(self.identity, self.config))
        try:
            self.browser = await self.manager.__aenter__()
            options = {"locale": "zh-CN", "timezone_id": "Asia/Shanghai", "no_viewport": True,
                       "ignore_https_errors": True}
            if self.state.get("storage_state"):
                options["storage_state"] = self.state["storage_state"]
            self.context = await self.browser.new_context(**options)
        except BaseException:
            await self.close()
            raise

    async def snapshot(self):
        return {"storage_state": await self.context.storage_state(indexed_db=True)}

    async def _read_json(self, response):
        if response.status == 429:
            retry_after = response.headers.get("retry-after")
            delay = None
            if retry_after:
                try:
                    delay = max(0, float(retry_after))
                except ValueError:
                    from email.utils import parsedate_to_datetime
                    try:
                        delay = max(0, (parsedate_to_datetime(retry_after) - datetime.now(timezone.utc)).total_seconds())
                    except (TypeError, ValueError, OverflowError):
                        raise CrawlerError("protocol_changed", "The service supplied an invalid Retry-After header")
            raise CrawlerError("rate_limited", "The service requested a cooling period", retry_after=delay)
        if response.status >= 500:
            raise CrawlerError("network_error", "The target service is temporarily unavailable")
        if response.status != 200:
            raise CrawlerError("site_blocked", "The target interface did not return a successful HTTP status")
        body = await response.body()
        if len(body) > self.config.get("max_response_bytes", 32 * 1024 * 1024):
            raise CrawlerError("response_too_large", "A target response exceeds the configured size limit")
        try:
            return json.loads(body)
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise CrawlerError("protocol_changed", "A target interface returned a non-JSON response") from exc

    async def resolve_cities(self, names):
        page = await self.context.new_page()
        try:
            await page.goto(CTRIP_HOME, wait_until="domcontentloaded",
                            timeout=self.config.get("navigation_timeout", 30) * 1000)
            result = []
            for name in names:
                endpoint = "/international/search/api/poi/search?" + urlencode({"key": name, "filterAirport": "false"})
                async with page.expect_response(lambda response: response.request.method == "GET"
                        and response.url == "https://flights.ctrip.com" + endpoint,
                        timeout=self.config.get("action_timeout", 10) * 1000) as response_info:
                    await page.evaluate("endpoint => fetch(endpoint, {credentials: 'same-origin'}).then(() => null)", endpoint)
                payload = await self._read_json(await response_info.value)
                result.append(resolve_city_payload(payload, name))
            return result
        finally:
            await page.close()

    async def _collect_comfort(self, page, task, rows, queue, deadline, errors):
        from playwright.async_api import Error as BrowserError, TimeoutError as BrowserTimeout
        aliases = comfort_target_aliases(rows)
        responses, seen, attempted = [], set(), set()

        def timeout_ms():
            return max(1, min(self.config.get("action_timeout", 10), deadline - time.monotonic()) * 1000)

        async def read(response):
            try:
                if response.request.method != "POST":
                    return
                identity = comfort_request_identity(response.request.post_data_json, task, aliases)
                if identity is None or identity in seen:
                    return
                attempted.add(identity[0])
                payload = await asyncio.wait_for(self._read_json(response), max(0.01, deadline - time.monotonic()))
                seen.add(identity)
                responses.append({"flight_no": identity[0], "payload": payload})
            except CrawlerError as exc:
                if response.status == 429:
                    raise
                errors.add(exc.code)
            except (ValueError, TypeError):
                errors.add("protocol_changed")
            except (asyncio.TimeoutError, BrowserError):
                errors.add("network_error")

        async def drain():
            while not queue.empty() and time.monotonic() < deadline:
                await read(queue.get_nowait())

        await drain()
        targets = set(aliases.values())
        if targets - attempted and time.monotonic() < deadline:
            locators = page.locator(".flight-item .plane-No")
            try:
                await locators.first.wait_for(state="attached", timeout=timeout_ms())
                index = 0
                while time.monotonic() < deadline and targets - attempted:
                    count = await locators.count()
                    if index >= count:
                        # Wheel over the list so its normal scroll container loads the next cards.
                        await locators.last.scroll_into_view_if_needed(timeout=timeout_ms())
                        box = await locators.last.bounding_box(timeout=timeout_ms())
                        if box is None:
                            errors.add("page_details_not_loaded")
                            break
                        await page.mouse.move(box["x"] + box["width"] / 2, box["y"] + box["height"] / 2)
                        await page.mouse.wheel(0, 700)
                        try:
                            await page.wait_for_function("count => document.querySelectorAll('.flight-item .plane-No').length > count",
                                                         arg=count, timeout=max(1, min(1.5, deadline - time.monotonic()) * 1000))
                        except BrowserTimeout:
                            errors.add("page_details_not_loaded")
                            break
                        continue
                    locator = locators.nth(index)
                    index += 1
                    # The aircraft label is a child element; the flight number is direct text.
                    number = await locator.evaluate("el => Array.from(el.childNodes).filter(n => n.nodeType === 3).map(n => n.textContent).join('').trim()", timeout=timeout_ms())
                    operating = aliases.get(number)
                    if operating is None or operating in attempted:
                        continue
                    attempted.add(operating)
                    await page.mouse.move(0, 0)
                    await locator.hover(timeout=timeout_ms())
                    # Hover triggers the page's own request. Wait briefly without replaying it.
                    hover_deadline = min(deadline, time.monotonic() + 1.5)
                    while time.monotonic() < hover_deadline:
                        try:
                            response = await asyncio.wait_for(queue.get(), hover_deadline - time.monotonic())
                        except asyncio.TimeoutError:
                            break
                        await read(response)
                        if any(item[0] == operating for item in seen):
                            break
                    await drain()
            except BrowserTimeout:
                errors.add("page_details_timeout")
            except BrowserError:
                errors.add("network_error")
        await drain()
        if targets - attempted and time.monotonic() >= deadline:
            errors.add("comfort_budget_exhausted")
        result = apply_comfort(rows, responses)
        if errors and result["comfort_status"] in ("partial", "unavailable"):
            result["comfort_reason"] = ";".join(sorted(errors | {result["comfort_reason"]}))
        return result

    async def collect(self, task, deadline_seconds):
        from playwright.async_api import Error as BrowserError
        page = await self.context.new_page()
        queue = asyncio.Queue(maxsize=self.config.get("max_candidates", 64))
        comfort_queue = asyncio.Queue(maxsize=self.config.get("max_candidates", 64))
        comfort_errors = set()
        overflow = False
        chain = SearchChain(task)
        final_payload = None
        deadline = time.monotonic() + deadline_seconds
        retain_challenge = False

        def receive(response):
            nonlocal overflow
            parsed = urlparse(response.url)
            if parsed.hostname != "flights.ctrip.com":
                return
            path = parsed.path
            if path == SEARCH_API_PATH or path.startswith("/international/search/api/search/pull/"):
                try:
                    queue.put_nowait(response)
                except asyncio.QueueFull:
                    overflow = True
            elif self.config.get("comft_flight") and path == "/international/search/api/flight/comfort/getFlightComfort":
                try:
                    comfort_queue.put_nowait(response)
                except asyncio.QueueFull:
                    comfort_errors.add("response_too_large")

        page.on("response", receive)
        try:
            url = ("https://flights.ctrip.com/online/list/oneway-" + task["origin"]["code"].lower()
                   + "-" + task["destination"]["code"].lower() + "?" + urlencode({
                       "depdate": task["departure_date"], "cabin": "y_s_c_f", "adult": 1, "child": 0, "infant": 0}))
            await page.goto(url, wait_until="domcontentloaded", timeout=max(1, min(
                self.config.get("navigation_timeout", 30), deadline - time.monotonic())) * 1000)
            while final_payload is None:
                if overflow:
                    raise CrawlerError("response_too_large", "The target response queue exceeded its capacity")
                remaining = deadline - time.monotonic() - 10
                if remaining <= 0:
                    raise CrawlerError("response_timeout", "The search did not reach its explicit completion state")
                response = await asyncio.wait_for(queue.get(), remaining)
                path = urlparse(response.url).path
                try:
                    request_payload = response.request.post_data_json
                except (BrowserError, ValueError, TypeError, KeyError):
                    request_payload = None
                if not chain.matches_request(path, response.request.method, request_payload):
                    continue
                payload = await self._read_json(response)
                final_payload = chain.accept(path, response.request.method, request_payload, response.status, payload)
            observed_at = datetime.now(timezone.utc).isoformat()
            observation = normalize_response(final_payload, task, self.config, observed_at)
            if self.config.get("comft_flight"):
                comfort_deadline = min(deadline - 10, time.monotonic() + 15)
                observation.update(await self._collect_comfort(page, task, observation["rows"],
                                                              comfort_queue, comfort_deadline, comfort_errors))
            return observation
        except CrawlerError as exc:
            if exc.code == "challenge" and self.config.get("challenge_policy") == "wait_then_switch":
                self.challenge_page = page
                self.challenge_handle = uuid.uuid4().hex
                self.challenge_expires_at = time.monotonic() + 10
                exc.challenge_handle = self.challenge_handle
                retain_challenge = True
            raise
        except asyncio.TimeoutError as exc:
            raise CrawlerError("response_timeout", "No complete response arrived before the attempt deadline") from exc
        finally:
            page.remove_listener("response", receive)
            if not retain_challenge:
                await page.close()

    async def authenticate(self, account, timeout, challenge_handle=None):
        from playwright.async_api import TimeoutError as BrowserTimeout
        self.auth_checkpoint = None
        if not account:
            raise CrawlerError("needs_auth", "Authentication requires a configured account")
        page = None
        transferred_challenge = False
        if self.challenge_page:
            if (challenge_handle in (None, self.challenge_handle)
                    and time.monotonic() <= self.challenge_expires_at):
                page = self.challenge_page
                transferred_challenge = True
            else:
                await self.challenge_page.close()
            self.challenge_page = None
            self.challenge_handle = None
        page = page or await self.context.new_page()
        deadline = time.monotonic() + timeout
        authenticated = asyncio.Event()
        member_seen = asyncio.Event()
        member_failure = None
        jobs = set()
        checkpoint_at = 0.0

        def check_member_failure():
            if member_failure is not None:
                raise member_failure

        def action_timeout():
            check_member_failure()
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                raise CrawlerError("auth_timeout", "The authentication operation reached its deadline")
            return min(self.config.get("action_timeout", 10), remaining) * 1000

        async def check_member(response):
            nonlocal member_failure
            if not is_member_summary_request(response.url, response.request.method):
                return
            try:
                if response.status in (200, 429) and member_authenticated(await self._read_json(response)):
                    authenticated.set()
            except CrawlerError as exc:
                if response.status == 429:
                    member_failure = exc
            except ValueError:
                return
            finally:
                member_seen.set()

        def receive_member(response):
            if is_member_summary_request(response.url, response.request.method):
                job = asyncio.create_task(check_member(response))
                jobs.add(job)
                job.add_done_callback(jobs.discard)

        self.context.on("response", receive_member)
        try:
            if not transferred_challenge:
                await page.goto(CTRIP_HOME, wait_until="domcontentloaded", timeout=min(
                    self.config.get("navigation_timeout", 30), max(1, deadline - time.monotonic())) * 1000)
                try:
                    await asyncio.wait_for(member_seen.wait(), min(5, max(0.01, deadline - time.monotonic())))
                except asyncio.TimeoutError:
                    pass
                check_member_failure()
                if authenticated.is_set():
                    return {"authenticated": True}
                if self.config.get("headless", True) and not account.get("password"):
                    raise CrawlerError("needs_auth", "The saved session is not valid; headless login requires a password")
                login_url = "https://passport.ctrip.com/user/login?" + urlencode({"BackUrl": CTRIP_HOME})
                await page.goto(login_url, wait_until="domcontentloaded", timeout=min(
                    self.config.get("navigation_timeout", 30), max(1, deadline - time.monotonic())) * 1000)
                if account.get("username") and account.get("password"):
                    panel = page.locator('[data-testid="accountPanel"]')
                    await panel.wait_for(state="visible", timeout=action_timeout())
                    await panel.locator('[data-testid="accountNameInput"]').fill(account["username"], timeout=action_timeout())
                    await panel.locator('[data-testid="passwordInput"]').fill(account["password"], timeout=action_timeout())
                    await accept_login_agreement(page, action_timeout())
                    await panel.locator('[data-testid="loginButton"]').click(timeout=action_timeout())
            while time.monotonic() < deadline:
                check_member_failure()
                if authenticated.is_set():
                    return {"authenticated": True}
                challenge_visible = await page.locator('#sc_mobilevalidate').is_visible()
                if time.monotonic() >= checkpoint_at:
                    self.auth_checkpoint = {"state": await self.snapshot(), "confirmed": False,
                                            "challenge_visible": challenge_visible}
                    if self.emit:
                        self.emit('auth_checkpoint', self.auth_checkpoint)
                    checkpoint_at = time.monotonic() + 5
                if challenge_visible:
                    if self.config.get("headless", True) or self.config.get("challenge_policy") == "switch":
                        raise CrawlerError("challenge", "Login requires manual verification")
                await asyncio.sleep(min(0.25, max(0, deadline - time.monotonic())))
            raise CrawlerError("auth_timeout", "Login was not confirmed before the authentication deadline")
        except BrowserTimeout as exc:
            raise CrawlerError("auth_timeout", "A login page operation did not complete before its deadline") from exc
        finally:
            self.context.remove_listener("response", receive_member)
            for job in jobs:
                job.cancel()
            if jobs:
                await asyncio.gather(*jobs, return_exceptions=True)
            try:
                self.auth_checkpoint = {"state": await self.snapshot(), "confirmed": authenticated.is_set()}
            except Exception as exc:
                if authenticated.is_set():
                    raise CrawlerError("session_snapshot_failed", "Authenticated state could not be captured") from exc
            finally:
                await page.close()

    async def close(self):
        try:
            if self.context:
                await self.context.close()
        finally:
            self.context = None
            if self.manager:
                await self.manager.__aexit__(None, None, None)
            self.manager = None
            self.browser = None

# ================ worker ================
def _enable_child_subreaper():
    """Keep orphaned owned browser descendants reapable by this supervisor."""
    if sys.platform != 'linux':
        return
    import ctypes
    libc = ctypes.CDLL(None, use_errno=True)
    if libc.prctl(36, 1, 0, 0, 0) != 0:  # PR_SET_CHILD_SUBREAPER
        raise CrawlerError('process_cleanup', '无法建立 Linux 自有子进程回收边界')


class _ParentConnection:
    """Closing a POSIX pipe must also interrupt another thread blocked in recv."""

    def __init__(self, connection):
        self._connection = connection

    def send_bytes(self, *args, **kwargs):
        return self._connection.send_bytes(*args, **kwargs)

    def recv_bytes(self, *args, **kwargs):
        return self._connection.recv_bytes(*args, **kwargs)

    def close(self):
        if self._connection.closed:
            return
        if os.name == 'posix':
            import socket
            # multiprocessing's POSIX duplex Pipe is a socketpair.  Shutdown
            # wakes the reader thread; merely closing its FD can leave the
            # underlying socket referenced by a blocked recv indefinitely.
            try:
                duplicate = socket.fromfd(self._connection.fileno(), socket.AF_UNIX, socket.SOCK_STREAM)
                try:
                    duplicate.shutdown(socket.SHUT_RDWR)
                finally:
                    duplicate.close()
            except OSError:
                pass  # Already disconnected; close the original handle below.
        self._connection.close()


def _terminate_owned_processes(identities, timeout=2.0):
    import psutil
    processes = []
    for pid, created in reversed(list(identities.items())):
        try:
            process = psutil.Process(int(pid))
            if process.create_time() == created:
                processes.append(process)
                process.terminate()
        except psutil.NoSuchProcess:
            continue
        except psutil.AccessDenied as exc:
            raise CrawlerError('process_cleanup', '无法终止当前运行拥有的进程') from exc
    _, alive = psutil.wait_procs(processes, timeout=timeout)
    for process in alive:
        try:
            process.kill()
        except psutil.NoSuchProcess:
            pass
    _, alive = psutil.wait_procs(alive, timeout=timeout)
    if alive:
        raise CrawlerError('process_cleanup', '自有浏览器进程未能在关闭期限内退出')


def _windows_worker_job():
    """Bind browser descendants to worker lifetime, even if Python is killed."""
    if os.name != 'nt':
        return None
    import ctypes
    from ctypes import wintypes

    class BasicLimits(ctypes.Structure):
        _fields_ = [('PerProcessUserTimeLimit', ctypes.c_longlong),
                    ('PerJobUserTimeLimit', ctypes.c_longlong), ('LimitFlags', wintypes.DWORD),
                    ('MinimumWorkingSetSize', ctypes.c_size_t), ('MaximumWorkingSetSize', ctypes.c_size_t),
                    ('ActiveProcessLimit', wintypes.DWORD), ('Affinity', ctypes.c_size_t),
                    ('PriorityClass', wintypes.DWORD), ('SchedulingClass', wintypes.DWORD)]

    class IoCounters(ctypes.Structure):
        _fields_ = [(name, ctypes.c_ulonglong) for name in (
            'ReadOperationCount', 'WriteOperationCount', 'OtherOperationCount',
            'ReadTransferCount', 'WriteTransferCount', 'OtherTransferCount')]

    class ExtendedLimits(ctypes.Structure):
        _fields_ = [('BasicLimitInformation', BasicLimits), ('IoInfo', IoCounters),
                    ('ProcessMemoryLimit', ctypes.c_size_t), ('JobMemoryLimit', ctypes.c_size_t),
                    ('PeakProcessMemoryUsed', ctypes.c_size_t), ('PeakJobMemoryUsed', ctypes.c_size_t)]

    kernel = ctypes.WinDLL('kernel32', use_last_error=True)
    kernel.CreateJobObjectW.restype = wintypes.HANDLE
    kernel.CreateJobObjectW.argtypes = [ctypes.c_void_p, wintypes.LPCWSTR]
    kernel.SetInformationJobObject.argtypes = [wintypes.HANDLE, ctypes.c_int, ctypes.c_void_p, wintypes.DWORD]
    kernel.AssignProcessToJobObject.argtypes = [wintypes.HANDLE, wintypes.HANDLE]
    kernel.GetCurrentProcess.restype = wintypes.HANDLE
    kernel.CloseHandle.argtypes = [wintypes.HANDLE]
    job = kernel.CreateJobObjectW(None, None)
    limits = ExtendedLimits()
    limits.BasicLimitInformation.LimitFlags = 0x2000  # JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE
    if not job or not kernel.SetInformationJobObject(job, 9, ctypes.byref(limits), ctypes.sizeof(limits)) or not kernel.AssignProcessToJobObject(job, kernel.GetCurrentProcess()):
        if job:
            kernel.CloseHandle(job)
        raise CrawlerError('process_cleanup', '无法建立 Windows 子进程生命周期边界')
    # Keep the raw handle open until this process exits; closing kills this job.
    return job


def worker_main(connection, config, identity, state):
    signal.signal(signal.SIGINT, signal.SIG_IGN)
    if hasattr(signal, 'SIGBREAK'):
        signal.signal(signal.SIGBREAK, signal.SIG_IGN)
    job = None
    messages = queue.Queue(maxsize=2)
    disconnected = threading.Event()
    envelope = config['envelope']
    send_lock = threading.Lock()

    def send(kind, value=None, command=None, **extra):
        packet = {**envelope, **({k: command[k] for k in ('operation_id', 'attempt_id', 'auth_id', 'run_id', 'task_key', 'task_index') if k in command} if command else {}),
                  'type': kind, 'value': value, **extra}
        raw = json.dumps(packet, ensure_ascii=False, allow_nan=False).encode('utf-8')
        limit = 8 * 1024 * 1024 if kind in ('session', 'profile', 'auth_checkpoint') else config['max_result_bytes']
        if len(raw) > limit:
            raise CrawlerError('result_too_large', '工作进程结果超过通信上限')
        with send_lock:
            connection.send_bytes(raw)

    def read_commands():
        try:
            while True:
                packet = json.loads(connection.recv_bytes(64 * 1024))
                if not isinstance(packet, dict):
                    raise ValueError('command')
                messages.put(packet, timeout=2)
        except (EOFError, OSError, ValueError, queue.Full):
            disconnected.set()
            # Control-channel loss is sufficient: Windows can retain the old
            # parent PID after parent exit, and the event loop may be blocked.
            try:
                import psutil
                owned = {p.pid: p.create_time() for p in psutil.Process().children(recursive=True)}
                _terminate_owned_processes(owned, timeout=min(2, config['close_timeout']))
            finally:
                os._exit(4)

    async def next_command():
        while not disconnected.is_set():
            try:
                return messages.get_nowait()
            except queue.Empty:
                await asyncio.sleep(0.05)
        raise EOFError

    async def run():
        nonlocal identity, job
        session = None
        try:
            job = _windows_worker_job()
            if identity is None:
                identity = await asyncio.to_thread(generate_identity, config)
                send('profile', identity)
                ack = await next_command()
                if ack.get('type') != 'profile_accepted':
                    raise CrawlerError('ipc_invalid', '会话身份尚未保存')
            active_command = None

            def emit_browser(kind, value):
                if kind == 'auth_checkpoint' and active_command and active_command.get('type') == 'auth':
                    send(kind, value, active_command)

            session = BrowserSession(config, identity, state, emit_browser)
            await session.start()
            send('ready')
            snapshot_sequence = 0
            while True:
                command = await next_command()
                active_command = command
                if command.get('type') == 'shutdown':
                    break
                if any(command.get(k) != envelope[k] for k in ('worker_generation', 'account_alias', 'binding_epoch')):
                    raise CrawlerError('ipc_invalid', '工作进程账号绑定不匹配')
                try:
                    kind = command['type']
                    timeout = command['timeout']
                    if kind == 'resolve':
                        value = await asyncio.wait_for(session.resolve_cities(command['value']['names']), timeout)
                    elif kind == 'collect':
                        value = await asyncio.wait_for(session.collect(command['value']['task'], timeout), timeout)
                    elif kind == 'auth':
                        value = await asyncio.wait_for(session.authenticate(command['value']['account'], timeout), timeout)
                    else:
                        raise CrawlerError('ipc_invalid', '不支持的工作进程命令')
                    snapshot = await session.snapshot()
                    snapshot_sequence += 1
                    send('session', {'identity': identity, 'state': snapshot}, command,
                         snapshot_sequence=snapshot_sequence)
                    send('result', value, command, snapshot_sequence=snapshot_sequence)
                except (CrawlerError, asyncio.TimeoutError) as exc:
                    checkpoint = getattr(session, 'auth_checkpoint', None)
                    if command.get('type') == 'auth' and checkpoint:
                        send('auth_checkpoint', checkpoint, command)
                    if isinstance(exc, asyncio.TimeoutError):
                        exc = CrawlerError('response_timeout', '浏览器操作超时')
                    send('failure', command=command, code=exc.code,
                         message=safe_message(exc), retry_after=exc.retry_after)
                except Exception as exc:
                    send('failure', command=command, code='browser_error', message=type(exc).__name__)
        except EOFError:
            pass
        except Exception as exc:
            try:
                send('startup_failure', code=getattr(exc, 'code', 'browser_startup'), message=safe_message(exc))
            except (OSError, EOFError):
                pass
        finally:
            if session:
                try:
                    await asyncio.wait_for(session.close(), config['close_timeout'])
                except (Exception, asyncio.CancelledError):
                    # Parent owns the final process-tree cleanup after grace.
                    pass
            try:
                send('stopped')
            except (OSError, EOFError):
                pass

    reader = threading.Thread(target=read_commands, daemon=True, name='ctrip-command-reader')
    reader.start()
    try:
        asyncio.run(run())
    finally:
        disconnected.set()
        connection.close()


class WorkerClient:
    """One supervised worker; no browser objects or blocking pipe I/O on parent."""

    def __init__(self, config, identity, state, *, generation, alias=None,
                 on_profile=None, on_session=None, on_checkpoint=None, owner_path=None, target=None):
        self.config = copy.deepcopy(config)
        self.generation = generation
        self.envelope = {'protocol_version': 1, 'worker_generation': generation,
                         'account_alias': alias, 'binding_epoch': generation}
        self.config['envelope'] = self.envelope
        self.config['parent_pid'] = os.getpid()
        self.identity, self.state = identity, state
        self.on_profile, self.on_session = on_profile, on_session
        self.on_checkpoint = on_checkpoint
        self.owner_path = owner_path
        self.target = target or worker_main
        self.context = multiprocessing.get_context('spawn')
        _enable_child_subreaper()
        parent_connection, self.child_connection = self.context.Pipe()
        self.connection = _ParentConnection(parent_connection)
        self.process = self.context.Process(target=self.target,
            args=(self.child_connection, self.config, identity, state), name='ctrip-browser')
        self.incoming = queue.Queue(maxsize=1)
        self.outgoing = queue.Queue(maxsize=1)
        self.stop_event = threading.Event()
        self.identities = {}
        self.threads = []
        self.last_sample = 0.0
        self.closed = False
        self.snapshot_sequence = 0

    def __enter__(self):
        return self

    def __exit__(self, *_):
        self.close()

    def _deliver(self, value):
        while not self.stop_event.is_set():
            try:
                self.incoming.put(value, timeout=0.1)
                return
            except queue.Full:
                continue

    def _receive(self):
        try:
            while not self.stop_event.is_set():
                raw = self.connection.recv_bytes(self.config['max_result_bytes'])
                value = json.loads(raw)
                if not isinstance(value, dict):
                    raise ValueError('message')
                self._deliver(value)
        except (OSError, EOFError, ValueError) as exc:
            self._deliver({'type': 'channel_closed', 'message': type(exc).__name__})

    def _send(self):
        try:
            while not self.stop_event.is_set():
                try:
                    value = self.outgoing.get(timeout=0.1)
                except queue.Empty:
                    continue
                self.connection.send_bytes(value)
        except (OSError, EOFError) as exc:
            self._deliver({'type': 'channel_closed', 'message': type(exc).__name__})

    def send(self, kind, value=None, **extra):
        packet = {**self.envelope, 'type': kind, 'value': value, **extra}
        raw = json.dumps(packet, ensure_ascii=False, allow_nan=False).encode('utf-8')
        if len(raw) > 64 * 1024:
            raise CrawlerError('ipc_invalid', '命令超过通信上限')
        try:
            self.outgoing.put_nowait(raw)
        except queue.Full as exc:
            raise CrawlerError('ipc_blocked', '命令发送通道阻塞') from exc

    def _sample(self, enforce_limit=True):
        import psutil
        if time.monotonic() - self.last_sample < 0.5:
            return
        self.last_sample = time.monotonic()
        try:
            parent = psutil.Process(self.process.pid)
            processes = [parent, *parent.children(recursive=True)]
            total = 0
            changed = False
            for process in processes:
                try:
                    created = process.create_time()
                    if self.identities.get(process.pid) != created:
                        self.identities[process.pid] = created
                        changed = True
                    total += process.memory_info().rss
                except psutil.NoSuchProcess:
                    continue
            if self.owner_path and changed:
                atomic_json(self.owner_path, {'owner_pid': os.getpid(), 'processes': self.identities})
            if enforce_limit and total > self.config['memory_limit_mb'] * 1024 * 1024:
                raise CrawlerError('memory_limit', '浏览器进程树超过内存上限')
        except psutil.NoSuchProcess:
            return

    def _next(self, deadline):
        while time.monotonic() < deadline:
            self._sample()
            try:
                packet = self.incoming.get(timeout=min(0.1, max(0.001, deadline - time.monotonic())))
            except queue.Empty:
                if not self.process.is_alive():
                    raise CrawlerError('worker_crashed', '浏览器工作进程已退出')
                continue
            if time.monotonic() >= deadline:
                break
            if packet.get('type') == 'channel_closed':
                raise CrawlerError('ipc_closed', '浏览器通信连接已关闭')
            if any(packet.get(k) != v for k, v in self.envelope.items()):
                raise CrawlerError('ipc_invalid', '拒绝账号或代次不匹配的消息')
            return packet
        raise CrawlerError('worker_timeout', '工作进程未在截止时间内返回完整结果')

    def start(self, timeout=None):
        self.process.start()
        self.child_connection.close()
        for target in (self._receive, self._send):
            thread = threading.Thread(target=target, daemon=True)
            thread.start()
            self.threads.append(thread)
        deadline = time.monotonic() + (timeout or self.config['startup_timeout'])
        while True:
            packet = self._next(deadline)
            if packet['type'] == 'profile':
                self.identity = packet['value']
                if not self.on_profile:
                    raise CrawlerError('state_invalid', '缺少会话身份保存处理器')
                self.on_profile(self.identity)
                self.send('profile_accepted')
            elif packet['type'] == 'ready':
                return
            elif packet['type'] == 'startup_failure':
                raise CrawlerError(packet['code'], packet['message'])
            else:
                raise CrawlerError('ipc_invalid', '启动期间收到无效消息')

    def call(self, kind, value, *, timeout, attempt_id=None, auth_id=None):
        operation = uuid.uuid4().hex
        starting_sequence = self.snapshot_sequence
        extra = {'operation_id': operation, 'timeout': timeout}
        if attempt_id:
            extra['attempt_id'] = attempt_id
        if auth_id:
            extra['auth_id'] = auth_id
        if kind == 'collect':
            task = value['task']
            extra.update(run_id=task['run_id'], task_key=task['key'], task_index=task['index'])
        self.send(kind, value, **extra)
        deadline = time.monotonic() + timeout
        while True:
            packet = self._next(deadline)
            if packet.get('operation_id') != operation:
                raise CrawlerError('ipc_invalid', '拒绝迟到的操作结果')
            for key in ('attempt_id', 'auth_id', 'run_id', 'task_key', 'task_index'):
                if key in extra and packet.get(key) != extra[key]:
                    raise CrawlerError('ipc_invalid', '拒绝任务或认证身份不符的结果')
            if packet['type'] == 'auth_checkpoint':
                if kind != 'auth':
                    raise CrawlerError('ipc_invalid', '非认证操作不能更新认证候选状态')
                if self.on_checkpoint:
                    self.on_checkpoint(packet['value'])
            elif packet['type'] == 'session':
                sequence = packet.get('snapshot_sequence')
                if sequence != self.snapshot_sequence + 1:
                    raise CrawlerError('ipc_invalid', '认证快照序号不连续')
                self.state = packet['value']['state']
                if self.on_session:
                    self.on_session(packet['value'])
                self.snapshot_sequence = sequence
            elif packet['type'] == 'result':
                if (self.snapshot_sequence <= starting_sequence
                        or packet.get('snapshot_sequence') != self.snapshot_sequence):
                    raise CrawlerError('ipc_invalid', '结果引用了未持久保存的认证快照')
                return packet['value']
            elif packet['type'] == 'failure':
                raise CrawlerError(packet['code'], packet['message'], retry_after=packet.get('retry_after'))
            else:
                raise CrawlerError('ipc_invalid', '收到未知操作响应')

    def close(self):
        if self.closed:
            return
        self.closed = True
        cleanup_error = None
        if self.process.pid:
            try:
                try:
                    # Do not let rate limiting hide a just-created descendant.
                    self.last_sample = 0.0
                    self._sample(enforce_limit=False)
                except Exception as exc:
                    cleanup_error = exc
                if self.process.is_alive():
                    try:
                        self.send('shutdown')
                    except CrawlerError:
                        pass
                    self.process.join(self.config['close_timeout'])
                # multiprocessing alone owns waitpid/reaping for this process.
                # psutil.wait_procs on it steals the exit status on POSIX and
                # leaves multiprocessing.Process.is_alive() permanently true.
                if self.process.is_alive():
                    self.process.terminate()
                    self.process.join(timeout=min(2, self.config['close_timeout']))
                if self.process.is_alive():
                    self.process.kill()
                    self.process.join(timeout=2)
                if self.process.is_alive():
                    raise CrawlerError('process_cleanup', '工作进程未能在关闭期限内退出')
                descendants = {pid: created for pid, created in self.identities.items()
                               if int(pid) != self.process.pid}
                _terminate_owned_processes(descendants, timeout=min(2, self.config['close_timeout']))
            except Exception as exc:
                cleanup_error = exc
                if self.process.is_alive():
                    self.process.kill()
                    self.process.join(timeout=2)
        self.stop_event.set()
        self.connection.close()
        self.child_connection.close()
        for thread in self.threads:
            thread.join(timeout=1)
        if any(t.is_alive() for t in self.threads):
            raise CrawlerError('ipc_cleanup', '通信线程未退出，停止运行以避免泄漏')
        if cleanup_error:
            raise cleanup_error

# ================ main ================
class Runner:
    """Sequential parent control flow; all durable changes have one owner."""

    def __init__(self, config, *, worker_factory=None):
        self.config = copy.deepcopy(config)
        self.output = Path(config.get('output') or Path(__file__).resolve().parent / 'data').resolve()
        self.worker_factory = worker_factory or WorkerClient
        self.worker = None
        self.alias = None
        self.pool = None
        self.store = None
        self.control = {}
        self.control_path = None
        self.generation = 0
        self.completed_with_worker = 0
        self.stop_requested = False
        self.logger = logging.getLogger('ctrip')

    def save(self):
        atomic_json(self.control_path, self.control)

    def _check_stop(self):
        if self.stop_requested:
            raise KeyboardInterrupt

    def _disk_check(self):
        if shutil.disk_usage(self.output).free < self.config['disk_reserve_mb'] * 1024 * 1024:
            raise CrawlerError('storage_error', '输出目录可用空间不足，停止派发')

    def _site_deadline(self):
        path = self.output / '.site.json'
        state = read_json(path) if path.exists() else {'schema_version': SCHEMA_VERSION}
        if not isinstance(state, dict) or state.get('schema_version') != SCHEMA_VERSION:
            raise CrawlerError('state_invalid', '站点冷却状态格式不兼容')
        candidates = [value for value in (state.get('server_not_before'),
                                          self.control.get('server_not_before')) if value]
        try:
            deadline = max(candidates, key=parse_utc) if candidates else None
            if deadline:
                parse_utc(deadline)
        except (AttributeError, TypeError, ValueError) as exc:
            raise CrawlerError('state_invalid', '站点冷却时间无效') from exc
        if deadline and deadline != state.get('server_not_before'):
            atomic_json(path, {'schema_version': SCHEMA_VERSION, 'server_not_before': deadline})
        return deadline

    def _site_gate(self):
        deadline = self._site_deadline()
        if deadline and parse_utc(deadline) > datetime.now(timezone.utc):
            raise CrawlerError('rate_limited', '站点的服务端等待尚未结束，新批次和登录不能绕过')

    def _handle_site_limit(self, error, *, allow_wait=True):
        try:
            seconds = float(error.retry_after) if error.retry_after is not None else 600.0
            if not math.isfinite(seconds) or seconds < 0:
                raise ValueError('retry_after')
        except (TypeError, ValueError) as exc:
            raise CrawlerError('protocol_changed', '服务端等待时间无效') from exc
        until = (datetime.now(timezone.utc) + timedelta(seconds=seconds)).isoformat()
        previous = self._site_deadline()
        if previous:
            until = max((previous, until), key=parse_utc)
        # Publish output-wide policy first. A crash before progress.save cannot
        # allow another batch or an independent login to bypass the wait.
        atomic_json(self.output / '.site.json', {'schema_version': SCHEMA_VERSION,
                                               'server_not_before': until})
        self.control['server_not_before'] = until
        self.save()
        remaining = max(0, (parse_utc(until) - datetime.now(timezone.utc)).total_seconds())
        if not allow_wait or self.control.get('rate_limit_recoveries', 0) >= 1 or remaining > 600:
            raise CrawlerError('rate_limited', '站点已限流，最早恢复时间已保存')
        self.control['rate_limit_recoveries'] = 1
        self.save()
        self._wait_until(until)
        self._site_gate()

    def _session_file(self, alias):
        return self.pool.session_path(alias) if alias is not None else self.output / 'sessions' / 'anonymous.json'

    def _recover_owner(self, owner_path):
        """Retire only exact process identities recorded by this operation."""
        owner_path = Path(owner_path)
        if not owner_path.exists():
            return
        if not owner_path.resolve().is_relative_to(self.output):
            raise CrawlerError('process_cleanup', '进程归属记录不在当前输出目录内')
        record = read_json(owner_path)
        identities = record.get('processes')
        if (type(record.get('owner_pid')) is not int or record['owner_pid'] <= 0
                or not isinstance(identities, dict)):
            raise CrawlerError('process_cleanup', '进程归属记录不完整，拒绝推测清理目标')
        import psutil
        try:
            protected = {os.getpid(), *(process.pid for process in psutil.Process().parents())}
            matching = {}
            for raw_pid, created in identities.items():
                if (not re.fullmatch(r'[1-9][0-9]*', str(raw_pid)) or isinstance(created, bool)
                        or not isinstance(created, (int, float)) or not math.isfinite(created) or created <= 0):
                    raise CrawlerError('process_cleanup', '进程身份记录无效')
                pid = int(raw_pid)
                try:
                    process = psutil.Process(pid)
                    if process.create_time() != created:
                        # The recorded resource ended; a reused PID belongs to
                        # another process and grants no cleanup authority.
                        continue
                    if pid in protected:
                        raise CrawlerError('process_cleanup', '归属记录指向当前父进程或其祖先，拒绝清理')
                    matching[pid] = created
                except psutil.NoSuchProcess:
                    continue
            # Inspect every entry before terminating any process. Inspection
            # denial is not evidence that a resource is absent.
            _terminate_owned_processes(matching)
            for pid, created in matching.items():
                try:
                    process = psutil.Process(pid)
                    if (process.create_time() == created and process.is_running()
                            and process.status() != psutil.STATUS_ZOMBIE):
                        raise CrawlerError('process_cleanup', '已记录的自有进程未能退出')
                except psutil.NoSuchProcess:
                    continue
        except psutil.AccessDenied as exc:
            raise CrawlerError('process_cleanup', '无法确认或清理已记录进程的权限') from exc
        atomic_json(owner_path, dict(record, processes={}, recovered_at=utc_now()))

    def _load_session(self, alias):
        path = self._session_file(alias)
        return read_json(path) if path.exists() else None

    def _save_identity(self, identity):
        current = self._load_session(self.alias)
        if current:
            if stable_hash(current['identity']) != stable_hash(identity):
                raise CrawlerError('session_incompatible', '浏览器身份发生变化，请使用独立输出目录重新认证')
            return
        snapshot = {'schema_version': SCHEMA_VERSION, 'session_identity_id': uuid.uuid4().hex,
                    'session_revision': 0, 'identity': identity, 'state': None}
        if self.alias is None:
            atomic_json(self._session_file(None), snapshot)
        else:
            self.pool.initialize_session(self.alias, snapshot)

    def _save_session(self, value):
        previous = self._load_session(self.alias)
        if not previous or stable_hash(previous['identity']) != stable_hash(value['identity']):
            raise CrawlerError('session_incompatible', '拒绝不匹配身份的认证快照')
        snapshot = dict(previous, state=value['state'], session_revision=previous['session_revision'] + 1,
                        updated_at=utc_now())
        if self.alias is None:
            atomic_json(self._session_file(None), snapshot)
        else:
            self.pool.commit_session(self.alias, snapshot, control_path=self.control_path, control=self.control)

    def _save_auth_candidate(self, value):
        previous = self._load_session(self.alias)
        if self.alias is None or not previous or not isinstance(value.get('state'), dict):
            raise CrawlerError('state_invalid', '认证候选状态没有合法身份')
        path = self.pool.session_path(self.alias).with_name('auth-candidate.json')
        atomic_json(path, {'schema_version': SCHEMA_VERSION, 'account_alias': self.alias,
                          'session_identity_id': previous['session_identity_id'],
                          'state': value['state'], 'confirmed': False,
                          'challenge_visible': bool(value.get('challenge_visible')), 'saved_at': utc_now()})
        if value.get('challenge_visible') and not self.control.get('challenge_notified'):
            self.logger.warning('需要在当前浏览器中完成手机验证；账号=%s，程序不会自动发送短信。', self.alias)
            self.control['challenge_notified'] = True
            self.save()

    def _close_worker(self):
        if self.worker is not None:
            worker, self.worker = self.worker, None
            worker.close()
        self.completed_with_worker = 0

    def _recover_budgets(self):
        recover_attempt_budget(self.control)
        auth = self.control.setdefault('auth', {'used': 0.0, 'reserved': 0.0})
        auth['used'] += auth.get('reserved', 0)
        auth['reserved'] = 0
        startup = self.control.get('startup')
        if startup and startup.get('reserved'):
            if self.control.get('current'):
                self.control['current']['work_used'] += startup['reserved']
            startup['used'] = startup.get('used', 0) + startup['reserved']
            startup['reserved'] = 0
        self.save()

    def _ensure_worker(self, alias):
        self._check_stop()
        self._site_gate()
        if self.worker is not None and self.alias == alias:
            return
        self._close_worker()
        self.alias = alias
        startup = self.control.get('startup')
        if not startup or startup.get('complete') or startup.get('alias') != alias:
            startup = {'id': uuid.uuid4().hex, 'alias': alias, 'attempts': 0, 'used': 0.0, 'reserved': 0.0, 'complete': False}
            self.control['startup'] = startup
        while startup['attempts'] < 3:
            self._check_stop()
            saved = self._load_session(alias)
            state = saved.get('state') if saved else None
            if self.config.get('explicit_login') and saved:
                candidate_path = self._session_file(alias).with_name('auth-candidate.json')
                if candidate_path.exists():
                    candidate = read_json(candidate_path)
                    if candidate.get('session_identity_id') != saved['session_identity_id'] or candidate.get('account_alias') != alias:
                        raise CrawlerError('session_incompatible', '认证候选状态与账号身份不符')
                    if parse_utc(candidate['saved_at']) > parse_utc(saved.get('updated_at', '0001-01-01T00:00:00+00:00')):
                        state = candidate['state']
            current = self.control.get('current')
            remaining = self.config['task_budget'] - current['work_used'] if current else self.config['startup_timeout'] * 3 - startup['used']
            if remaining <= 0:
                raise CrawlerError('task_exhausted', '浏览器恢复时间预算已耗尽')
            timeout = min(self.config['startup_timeout'], remaining)
            self.generation = max(self.generation, self.control.get('generation', 0)) + 1
            self.control['generation'] = self.generation
            startup['attempts'] += 1
            startup['reserved'] = timeout
            self.save()
            began = time.monotonic()
            worker_config = dict(self.config, account_alias=alias)
            if alias is not None:
                worker_config['account'] = account_credentials(self.pool.config[alias])
            worker = self.worker_factory(worker_config, saved.get('identity') if saved else None,
                state, generation=self.generation, alias=alias,
                on_profile=self._save_identity, on_session=self._save_session,
                on_checkpoint=self._save_auth_candidate,
                owner_path=self.control_path.parent / 'owner.json')
            self.worker = worker
            try:
                worker.start(timeout=timeout)
                elapsed = min(timeout, time.monotonic() - began)
                startup['used'] += elapsed
                startup['reserved'] = 0
                startup['complete'] = True
                if current:
                    current['work_used'] += elapsed
                self.save()
                return
            except CrawlerError as exc:
                elapsed = min(timeout, time.monotonic() - began)
                startup['used'] += elapsed
                startup['reserved'] = 0
                if current:
                    current['work_used'] += elapsed
                self.save()
                self._close_worker()
                if exc.code not in ('worker_timeout', 'worker_crashed', 'ipc_closed', 'browser_startup'):
                    raise
                self.logger.warning('worker_start_failed generation=%s code=%s', self.generation, exc.code)
        raise CrawlerError('worker_startup_exhausted', '浏览器启动次数已耗尽，进度已保存')

    def _mark_account(self, state, reason, *, seconds=None):
        if self.alias is None:
            raise CrawlerError('needs_auth', '匿名会话需要认证，请配置账号池')
        until = (datetime.now(timezone.utc) + timedelta(seconds=seconds)).isoformat() if seconds else None
        self.pool.mark(self.alias, state, reason, cooldown_until=until,
                       control_path=self.control_path, control=self.control,
                       source={'run_id': self.control.get('run_id'), 'task_index': self.control.get('cursor'),
                               'attempt_id': (self.control.get('current') or {}).get('attempt_id')})

    def _choose_account(self):
        if not self.config['login_allowed']:
            return None
        self.pool.reconcile(control=self.control, control_path=self.control_path)
        alias = self.pool.select(self.alias or self.control.get('preferred_alias'), self.control.get('blocked_accounts', {}))
        if alias is None:
            reasons = {a: self.pool.record(a)['state'] for a in self.pool.config}
            self.control['pool_summary'] = reasons
            self.save()
            raise CrawlerError('account_pool_exhausted', '当前任务没有可用账号，请完成 --login 后恢复；任务预算不会重置')
        self.control['preferred_alias'] = alias
        self.save()
        return alias

    def _authenticate(self, *, explicit=False, manual=False):
        self._check_stop()
        self._site_gate()
        if self.alias is None:
            raise CrawlerError('needs_auth', '匿名运行无法自动登录')
        used = self.control.setdefault('auth_used_aliases', [])
        if self.alias in used and not explicit:
            self._mark_account('cooldown', 'authentication_budget', seconds=self.config['cooldown_seconds'])
            raise CrawlerError('account_unavailable', '此任务对该账号的认证机会已用完')
        auth = self.control.setdefault('auth', {'used': 0.0, 'reserved': 0.0})
        total = self.config['standalone_auth_timeout'] if explicit else self.config['auth_budget']
        timeout = self.config['standalone_auth_timeout'] if explicit else (
            self.config['challenge_timeout'] if manual else self.config['login_timeout'])
        timeout = min(timeout, total - auth['used'])
        if timeout <= 0:
            raise CrawlerError('auth_exhausted', '认证总预算已耗尽')
        if self.alias not in used:
            used.append(self.alias)
        auth.update(id=uuid.uuid4().hex, reserved=timeout, alias=self.alias)
        self.save()
        began = time.monotonic()
        account = account_credentials(self.pool.config[self.alias])
        try:
            value = self.worker.call('auth', {'account': account}, timeout=timeout, auth_id=auth['id'])
            if not isinstance(value, dict) or not value.get('authenticated'):
                raise CrawlerError('auth_failed', '浏览器未确认登录成功')
            snapshot = self._load_session(self.alias)
            if explicit:
                self.pool.commit_session(self.alias, snapshot, explicit_auth=True, auth_id=auth['id'],
                                         control_path=self.control_path, control=self.control)
            else:
                self.pool.mark(self.alias, 'ready', 'authenticated', control_path=self.control_path, control=self.control)
        except CrawlerError as exc:
            if exc.code == 'rate_limited':
                self._handle_site_limit(exc, allow_wait=False)
            elif exc.code in ('credentials_invalid', 'account_disabled'):
                self._mark_account('disabled', exc.code)
            elif exc.code in ('needs_auth', 'challenge', 'auth_failed', 'auth_timeout', 'response_timeout', 'worker_timeout'):
                self._mark_account('cooldown', exc.code, seconds=self.config['cooldown_seconds'])
            raise
        finally:
            auth = self.control.setdefault('auth', auth)
            auth['used'] += min(timeout, time.monotonic() - began)
            auth['reserved'] = 0
            self.save()

    def _prepare_account(self):
        while True:
            self._check_stop()
            alias = self._choose_account()
            self._ensure_worker(alias)
            if alias is None or self.pool.record(alias)['state'] == 'ready':
                return
            try:
                self._authenticate()
                return
            except CrawlerError as exc:
                if exc.code not in ('account_unavailable', 'needs_auth', 'challenge', 'auth_failed', 'auth_timeout',
                                     'credentials_invalid', 'account_disabled', 'response_timeout', 'worker_timeout'):
                    raise
                self._close_worker()

    def _initialize(self, run_id, resume=False):
        self.store = FileStore(self.output, run_id)
        self.control_path = self.store.run_dir / 'initialization.json'
        self._recover_owner(self.store.run_dir / 'owner.json')
        if resume:
            self.control = read_json(self.control_path)
            saved_config = self.control.get('config')
            runtime_overrides = {'headless', 'challenge_policy'}
            if (not isinstance(saved_config, dict)
                    or {key: value for key, value in saved_config.items() if key not in runtime_overrides}
                    != {key: value for key, value in public_config(self.config).items() if key not in runtime_overrides}):
                raise CrawlerError('config_invalid', '初始化恢复配置与固定配置不同')
        else:
            self.control = {'schema_version': SCHEMA_VERSION, 'run_id': run_id,
                'operation_id': uuid.uuid4().hex, 'config': public_config(self.config),
                'dates': flight_dates(self.config), 'phase': 'initializing',
                'resolve_attempts': 0, 'resolve_used': 0.0, 'resolve_reserved': 0.0,
                'blocked_accounts': {}, 'auth_used_aliases': [], 'account_ack': {}}
            self.save()
        self.pool.reconcile(control=self.control, control_path=self.control_path)
        self._recover_budgets()
        self.control['resolve_used'] += self.control.get('resolve_reserved', 0)
        self.control['resolve_reserved'] = 0
        self.save()
        plan = None
        while self.control['resolve_attempts'] < 3:
            self._prepare_account()
            self._check_stop()
            timeout = min(self.config['attempt_timeout'], 180 - self.control['resolve_used'])
            if timeout <= 0:
                break
            self.control['resolve_attempts'] += 1
            self.control['resolve_reserved'] = timeout
            self.save()
            began = time.monotonic()
            try:
                self._site_gate()
                cities = self.worker.call('resolve', {'names': self.config['crawl_citys']}, timeout=timeout)
                if not isinstance(cities, list) or len(cities) != len(self.config['crawl_citys']):
                    raise CrawlerError('protocol_changed', '城市解析结果数量不一致')
                codes = [c['code'] for c in cities]
                if len(set(codes)) != len(codes) or any(not re.fullmatch(r'[A-Z]{3}', c) for c in codes):
                    raise CrawlerError('config_invalid', '城市身份重复或无效')
                for city in cities:
                    _files_safe_name(city['name'])
                plan = {'run_id': run_id, 'created_at': utc_now(), 'cities': cities,
                    'dates': self.control['dates'], 'config': public_config(self.config),
                    'options': {key: self.config[key] for key in ('direct_flight', 'comft_flight', 'rename_col')}}
                self.control['resolve_used'] += min(timeout, time.monotonic() - began)
                self.control['resolve_reserved'] = 0
                self.save()
                break
            except CrawlerError as exc:
                self.control['resolve_used'] += min(timeout, time.monotonic() - began)
                self.control['resolve_reserved'] = 0
                self.save()
                if exc.code == 'rate_limited':
                    self._handle_site_limit(exc)
                    continue
                if exc.code in ('needs_auth', 'challenge') and self.alias is not None:
                    self._mark_account('cooldown', exc.code, seconds=self.config['cooldown_seconds'])
                    self._close_worker()
                    continue
                raise
        if plan is None:
            raise CrawlerError('initialization_exhausted', '城市解析预算已耗尽')
        rate_limit_recoveries = self.control.get('rate_limit_recoveries', 0)
        try:
            progress = self.store.create(plan)
        except BaseException:
            # FileStore may already have published plan_complete before its
            # progress write failed. Never overwrite that recovery evidence
            # with the pre-publication in-memory initialization snapshot.
            self.control = read_json(self.control_path)
            raise
        self.control_path = self.store.progress_path
        self.control = progress
        self.control['rate_limit_recoveries'] = rate_limit_recoveries
        self.save()
        return plan

    def _resume(self, run_id):
        self.store = FileStore(self.output, run_id)
        if not self.store.plan_path.exists():
            return self._initialize(run_id, resume=True)
        self._recover_owner(self.store.run_dir / 'owner.json')
        plan, self.control = self.store.load()
        self.control_path = self.store.progress_path
        saved_config = plan['config']
        aliases = [a['alias'] for a in self.config['accounts']]
        if aliases != saved_config.get('account_aliases', []):
            raise CrawlerError('config_invalid', '恢复时账号池别名顺序不能改变')
        if (stable_hash(self.config['proxy']) if self.config['proxy'] else None) != saved_config.get('proxy_id'):
            raise CrawlerError('config_invalid', '恢复时代理配置不能静默改变')
        runtime_overrides = {'headless', 'challenge_policy'}
        for key, value in saved_config.items():
            if key in self.config and key not in runtime_overrides:
                self.config[key] = value
        self.pool.reconcile(control=self.control, control_path=self.control_path)
        self.store.recover(self.control)
        self._recover_budgets()
        return plan

    def _wait_until(self, value):
        self._check_stop()
        while value and parse_utc(value) > datetime.now(timezone.utc):
            remaining = (parse_utc(value) - datetime.now(timezone.utc)).total_seconds()
            self._check_stop()
            time.sleep(min(0.25, remaining))
        self._check_stop()

    def _collect_plan(self, plan):
        total = len(plan['cities']) * (len(plan['cities']) - 1) * len(plan['dates'])
        if self.control['cursor'] > total:
            raise CrawlerError('state_invalid', '恢复点超出固定计划')
        if self.control['cursor'] == total:
            self.control['status'] = 'completed'
            self.save()
            return 0
        self._site_gate()
        for task in iter_tasks(plan):
            if task['index'] < self.control['cursor']:
                continue
            if self.stop_requested:
                raise KeyboardInterrupt
            self._disk_check()
            if date.fromisoformat(task['departure_date']) < datetime.now(ZoneInfo(self.config['timezone'])).date():
                raise CrawlerError('expired', '当前任务出发日期已过去，固定计划不会自动改日')
            if self.control.get('current') is None:
                new = new_task_control(task['index'], len(self.config['accounts']) or 1)
                self.control.update(new)
                self.control['auth'] = {'used': 0.0, 'reserved': 0.0}
                self.save()
            while True:
                self._check_stop()
                current = self.control['current']
                if current['attempt_count'] >= current['max_attempts'] or current['work_used'] >= self.config['task_budget']:
                    raise CrawlerError('task_exhausted', '当前任务预算已耗尽；resume 不会重置预算')
                self._wait_until(self.control.get('next_attempt_at'))
                self._prepare_account()
                self._wait_until(self.control.get('next_search_at'))
                self._site_gate()
                current = reserve_attempt(self.control, self.alias, self.generation,
                                          self.config['attempt_timeout'], self.config['task_budget'])
                self.control['next_search_at'] = (datetime.now(timezone.utc) + timedelta(seconds=self.config['crawl_interval'])).isoformat()
                self.save()
                began = time.monotonic()
                committed = False
                try:
                    task['account_alias'] = self.alias
                    task['binding_epoch'] = self.generation
                    result = self.worker.call('collect', {'task': task}, timeout=current['reserved'], attempt_id=current['attempt_id'])
                    settle_attempt(self.control, time.monotonic() - began)
                    self.save()
                    result.setdefault('columns', list(CSV_FIELDS))
                    self.store.publish(task, result, self.control)
                    committed = True
                    self.completed_with_worker += 1
                    self.logger.info('task_done index=%s/%s status=%s rows=%s price_status=%s',
                                     task['index'] + 1, total, result['status'], len(result['rows']), result['price_status'])
                    if self.completed_with_worker >= self.config['recycle_tasks']:
                        self._close_worker()
                    break
                except CrawlerError as exc:
                    if (committed or self.control.get('current') is None
                            or self.control.get('staging') or self.control.get('publish_intent')):
                        raise
                    settle_attempt(self.control, time.monotonic() - began)
                    self.control['last_error'] = {'code': exc.code, 'task_index': task['index'], 'at': utc_now()}
                    self.save()
                    self.logger.warning('task_failed index=%s attempt=%s code=%s', task['index'],
                                        self.control['current']['attempt_count'], exc.code)
                    if exc.code in ('needs_auth', 'challenge') and self.alias is not None:
                        if self.config['challenge_policy'] == 'wait_then_switch':
                            try:
                                self._authenticate(manual=True)
                                continue
                            except CrawlerError as auth_error:
                                if auth_error.code not in ('needs_auth', 'auth_timeout', 'auth_failed', 'worker_timeout', 'response_timeout', 'account_unavailable'):
                                    raise
                        self._mark_account('cooldown', exc.code, seconds=self.config['cooldown_seconds'])
                        self._close_worker()
                        continue
                    if exc.code in ('credentials_invalid', 'account_disabled') and self.alias is not None:
                        self._mark_account('disabled', exc.code)
                        self._close_worker()
                        continue
                    if exc.code == 'rate_limited':
                        self._handle_site_limit(exc)
                        continue
                    if exc.code not in ('worker_timeout', 'worker_crashed', 'ipc_closed', 'response_timeout',
                                        'network_error', 'browser_error', 'memory_limit'):
                        raise
                    self._close_worker()
                    count = self.control['current']['attempt_count']
                    delays = self.config.get('retry_delays', [5, 15])
                    delay = delays[min(count - 1, len(delays) - 1)]
                    self.control['current']['work_used'] += delay
                    self.control['next_attempt_at'] = (datetime.now(timezone.utc) + timedelta(seconds=delay)).isoformat()
                    self.save()
        self.control['status'] = 'completed'
        self.save()
        return 0

    def run(self, *, resume=None, login=None):
        from filelock import FileLock, Timeout
        self.output.mkdir(parents=True, exist_ok=True)
        try:
            lock = FileLock(str(self.output / '.run.lock'), timeout=0)
            with lock:
                self.pool = AccountPool(self.output, self.config['accounts'])
                self.pool.reconcile()
                self._disk_check()
                self._site_gate()
                try:
                    if login:
                        if login not in self.pool.config:
                            raise CrawlerError('config_invalid', '未知的账号别名')
                        record = self.pool.record(login)
                        if record.get('server_not_before') and parse_utc(record['server_not_before']) > datetime.now(timezone.utc):
                            raise CrawlerError('rate_limited', '账号的服务端等待尚未结束')
                        self.config['headless'] = False
                        self.config['challenge_policy'] = 'wait_then_switch'
                        self.config['explicit_login'] = True
                        self.control_path = self.pool.session_path(login).parent / 'auth_control.json'
                        self._recover_owner(self.control_path.parent / 'owner.json')
                        self.control = {'operation_id': uuid.uuid4().hex, 'auth_used_aliases': [],
                                        'blocked_accounts': {}, 'account_ack': {}}
                        self.save()
                        self._ensure_worker(login)
                        self._authenticate(explicit=True, manual=True)
                        return 0
                    run_id = resume or datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ_') + uuid.uuid4().hex[:8]
                    self.logger.info('run=%s output=%s', run_id, self.output)
                    plan = self._resume(run_id) if resume else self._initialize(run_id)
                    return self._collect_plan(plan)
                except BaseException as exc:
                    if self.control_path and self.control_path.exists():
                        self.control['status'] = 'interrupted' if isinstance(exc, KeyboardInterrupt) else 'paused'
                        self.control['pause_reason'] = getattr(exc, 'code', type(exc).__name__)
                        self.save()
                    raise
                finally:
                    self._close_worker()
        except Timeout as exc:
            raise CrawlerError('output_locked', '输出目录正被另一个实例使用') from exc


def _resume_cli_config(config, run_id, output):
    """Read frozen non-secret settings before validating local credentials."""
    store = FileStore(output, run_id)
    if store.plan_path.exists():
        plan = read_json(store.plan_path)
        check = dict(plan)
        digest = check.pop('plan_hash', None)
        if (plan.get('run_id') != run_id or plan.get('schema_version') != SCHEMA_VERSION
                or digest != stable_hash(check)):
            raise CrawlerError('state_invalid', '恢复计划的版本、身份或摘要不符')
        frozen = plan.get('config')
    else:
        initialization = read_json(store.initialization_path)
        if initialization.get('run_id') != run_id or initialization.get('schema_version') != SCHEMA_VERSION:
            raise CrawlerError('state_invalid', '初始化恢复记录的版本或身份不符')
        frozen = initialization.get('config')
    if not isinstance(frozen, dict) or not isinstance(frozen.get('account_aliases'), list):
        raise CrawlerError('state_invalid', '恢复记录缺少规范配置或账号别名')
    local_accounts = config['accounts']
    if not isinstance(local_accounts, list) or any(not isinstance(item, dict) for item in local_accounts):
        raise CrawlerError('config_invalid', '本地账号配置必须为列表')
    by_alias = {}
    for account in local_accounts:
        alias = account.get('alias')
        if alias in by_alias:
            raise CrawlerError('config_invalid', '本地账号别名不能重复')
        by_alias[alias] = account
    accounts = []
    for alias in frozen['account_aliases']:
        if alias not in by_alias:
            raise CrawlerError('config_invalid', '恢复此批次需要在脚本中配置账号别名 ' + str(alias))
        accounts.append(copy.deepcopy(by_alias[alias]))
    for key, value in frozen.items():
        if key in config and key not in ('accounts', 'proxy', 'output'):
            config[key] = copy.deepcopy(value)
    config['accounts'] = accounts
    return config


def command_line(argv=None):
    parser = argparse.ArgumentParser(description='携程航班采集：Camoufox、独立单文件、账号池与可恢复文件输出',
        epilog='第三方安装：python -m pip install ' + ' '.join(f'{k}=={v}' for k, v in RUNTIME_REQUIREMENTS.items()) + '\n浏览器：python -m camoufox fetch ' + BROWSER_BUILD)
    operation = parser.add_mutually_exclusive_group()
    operation.add_argument('--resume', metavar='RUN_ID')
    operation.add_argument('--login', metavar='ALIAS')
    operation.add_argument('--check-environment', action='store_true')
    parser.add_argument('--output', type=Path)
    parser.add_argument('--cities', nargs='+', metavar='CITY')
    parser.add_argument('--begin-date')
    parser.add_argument('--days', type=int)
    parser.add_argument('--anonymous', action='store_true', help='显式匿名运行；需要认证时停止')
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument('--headed', action='store_true')
    mode.add_argument('--headless', action='store_true')
    parser.add_argument('--version', action='version', version=VERSION)
    args = parser.parse_args(argv)
    check_environment()
    if args.check_environment:
        browser_environment_check()
        print('运行依赖与指定 Camoufox 构建检查通过。')
        return 0
    config = copy.deepcopy(DEFAULT_CONFIG)
    if args.output:
        config['output'] = str(args.output.resolve())
    if args.resume:
        if args.cities or args.begin_date is not None or args.days is not None:
            raise CrawlerError('config_invalid', '恢复使用固定城市和日期；修改业务条件请创建新批次')
        output = Path(config['output'] or Path(__file__).resolve().parent / 'data').resolve()
        config = _resume_cli_config(config, args.resume, output)
        if args.anonymous and config['login_allowed']:
            raise CrawlerError('config_invalid', '恢复不能将账号批次改为匿名批次')
    if args.cities:
        config['crawl_citys'] = args.cities
    if args.begin_date:
        config['begin_date'] = args.begin_date
    if args.days is not None:
        config['crawl_days'] = args.days
    if args.anonymous:
        config['login_allowed'] = False
        config['accounts'] = []
    if args.headed:
        config['headless'] = False
    if args.headless:
        config['headless'] = True
    if args.login:
        config['headless'] = False
        config['challenge_policy'] = 'wait_then_switch'
    config = validate_config(config)
    browser_environment_check()
    output = Path(config['output'] or Path(__file__).resolve().parent / 'data').resolve()
    output.mkdir(parents=True, exist_ok=True)
    logger = logging.getLogger('ctrip')
    logger.setLevel(logging.INFO)
    formatter = logging.Formatter('%(asctime)s %(levelname)s %(message)s')
    console = logging.StreamHandler()
    console.setFormatter(formatter)
    rotating = logging.handlers.RotatingFileHandler(output / 'crawler.log', maxBytes=10 * 1024 * 1024,
                                                    backupCount=9, encoding='utf-8')
    rotating.setFormatter(formatter)
    logger.handlers[:] = [console, rotating]
    runner = Runner(config)
    interrupts = 0

    def stop(signum, frame):
        nonlocal interrupts
        interrupts += 1
        if interrupts == 1:
            runner.stop_requested = True
            logger.warning('停止派发，等待当前有界操作结束；再次中断将立即退出。')
        else:
            raise KeyboardInterrupt

    previous = signal.signal(signal.SIGINT, stop)
    try:
        result = runner.run(resume=args.resume, login=args.login)
        logger.info('finished status=%s stats=%s', result, runner.control.get('stats', {}))
        return result
    finally:
        signal.signal(signal.SIGINT, previous)
        for handler in logger.handlers:
            handler.close()
        logger.handlers.clear()


def main(argv=None):
    try:
        return command_line(argv)
    except KeyboardInterrupt:
        print('运行已中断，使用 --resume 恢复固定批次。', file=sys.stderr)
        return 130
    except CrawlerError as exc:
        print(f'{exc.code}: {safe_message(exc)}', file=sys.stderr)
        if exc.code in ('config_invalid', 'config_error', 'unsupported_mode', 'environment_invalid'):
            return 2
        if exc.code in ('needs_auth', 'account_pool_exhausted', 'rate_limited', 'protocol_changed', 'expired', 'session_incompatible'):
            return 3
        if exc.code.startswith(('storage', 'ipc', 'process', 'worker_startup')) or exc.code in ('output_locked', 'state_invalid'):
            return 4
        return 1
    except Exception as exc:
        print('unexpected_error: ' + type(exc).__name__, file=sys.stderr)
        return 4


if __name__ == '__main__':
    multiprocessing.freeze_support()
    raise SystemExit(main())
